// Local state - only this component needs it
function Toggle() {
  const [isOn, setIsOn] = useState(false);
  return <button onClick={() => setIsOn(!isOn)}>{isOn ? 'ON' : 'OFF'}</button>;
}

// Shared state - lift to common parent
function Parent() {
  const [count, setCount] = useState(0);
  return (
    <div>
      <Display count={count} />
      <Incrementor onIncrement={() => setCount(count + 1)} />
    </div>
  );
}

// Before: state trapped in one component
function TemperatureInput({ scale }) {
  const [temp, setTemp] = useState(0);
  // Other scale can't access this state!
}

// After: state lifted to parent
function Calculator() {
  const [temp, setTemp] = useState(0);
  const [scale, setScale] = useState('c');

  return (
    <>
      <TemperatureInput temp={temp} scale="c" onTempChange={setTemp} />
      <TemperatureInput temp={temp} scale="f" onTempChange={setTemp} />
    </>
  );
}

// Separate states that always change together
const [x, setX] = useState(0);
const [y, setY] = useState(0);

// Better: group into one state object
const [position, setPosition] = useState({ x: 0, y: 0 });

// Update with spread
const move = (dx, dy) => {
  setPosition(prev => ({ x: prev.x + dx, y: prev.y + dy }));
};

// WRONG - storing derived value
function Cart({ items }) {
  const [total, setTotal] = useState(0);

  useEffect(() => {
    setTotal(items.reduce((sum, item) => sum + item.price, 0));
  }, [items]);
  // ...
}

// CORRECT - calculate during render
function Cart({ items }) {
  const total = items.reduce((sum, item) => sum + item.price, 0);
  // ...
}
